-- Model: lna_zoomphoneactivity_user__zoom_phone_activity_hkey_curr
-- Description: Current active relationship for LNA_ZOOMPHONEACTIVITY_USER using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: CROSS_SOURCE_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNA_ZOOMPHONEACTIVITY_USER_HKEY AS LNA_ZOOMPHONEACTIVITY_USER_HKEY,
    l.ZOOM_PHONE_ACTIVITY_HKEY AS ZOOM_PHONE_ACTIVITY_HKEY,
    l.USER_HKEY AS USER_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls._AIRBYTE_EXTRACTED_AT

    ROW_NUMBER() OVER (
        PARTITION BY l.ZOOM_PHONE_ACTIVITY_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls._AIRBYTE_EXTRACTED_AT
    ) AS row_num

FROM {{ source('eli_dv_bv', 'lna_zoomphoneactivity_user') }} l
INNER JOIN {{ ref('las_zm_zoomphoneactivity_user_curr') }} ls
    ON l.LNA_ZOOMPHONEACTIVITY_USER_HKEY = ls.LNA_ZOOMPHONEACTIVITY_USER_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
